package dev.arabicgames.phone;
import android.content.*;import android.view.*;import android.widget.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35)
public class LocalTimingTest {
 @Test public void timingPreferencesPersistAndCannotLeaveSafeBounds(){Context c=RuntimeEnvironment.getApplication();LocalTiming.save(c,0,-1,99999);assertEquals(100,LocalTiming.interval(c));assertEquals(0,LocalTiming.settle(c));assertEquals(6000,LocalTiming.maxAge(c));LocalTiming.save(c,350,180,4500);assertEquals(350,LocalTiming.interval(c));assertEquals(180,LocalTiming.settle(c));}
 private Button button(View view,String title){if(view instanceof Button&&title.contentEquals(((Button)view).getText()))return (Button)view;if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++){Button b=button(((ViewGroup)view).getChildAt(i),title);if(b!=null)return b;}return null;}
 @Test public void fastestPresetAndSaveAreAvailableOnScreen(){try(var c=Robolectric.buildActivity(TimingActivity.class).setup()){View root=c.get().getWindow().getDecorView();button(root,"أسرع قراءة — استهلاك أعلى").performClick();button(root,"حفظ وتطبيق").performClick();assertEquals(100,LocalTiming.interval(c.get()));assertEquals(0,LocalTiming.settle(c.get()));assertTrue(c.get().isFinishing());}}
 @Test public void diagnosticExportHasOnlyFixedCounters()throws Exception{PipelineMetrics.superseded.incrementAndGet();String exported=PipelineMetrics.snapshot().toString();assertTrue(exported.contains("superseded"));assertFalse(exported.contains("source"));assertFalse(exported.contains("key"));}
 @Test public void stalledXboxFrameRequestIsReleasedAndLateCallbackInvalidated(){try(var c=Robolectric.buildActivity(XboxActivity.class).setup()){XboxActivity a=c.get();org.robolectric.util.ReflectionHelpers.setField(a,"pending",true);org.robolectric.util.ReflectionHelpers.setField(a,"pendingAt",android.os.SystemClock.elapsedRealtime()-4000L);org.robolectric.util.ReflectionHelpers.setField(a,"resumed",true);int before=org.robolectric.util.ReflectionHelpers.getField(a,"requestId");Runnable poll=org.robolectric.util.ReflectionHelpers.getField(a,"poll");poll.run();assertFalse((Boolean)org.robolectric.util.ReflectionHelpers.getField(a,"pending"));assertTrue((Integer)org.robolectric.util.ReflectionHelpers.getField(a,"requestId")>before);}}
}
